let ctx;
let colors = ['#083d77', '#38187d', '#d00000', '#ffba08', '#f654a9', '#cae509', '#42bfdd'];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	background(255);
	let region = width * 0.9;
	let cellCount = 6;
	let cellSize = region / cellCount;
	for (let j = 0; j < cellCount; j++) {
		for (let i = 0; i < cellCount; i++) {
			let x = map(i, 0, cellCount, 0, region) + (cellSize / 2) + (width - region)/2;
			let y = map(j, 0, cellCount, 0, region) + (cellSize / 2) + (height - region)/2;
			let w = cellSize * 0.75;
			let w1 = (w * random(0.25, 0.5));
			let w2 = (w - w1);
			let h1 = (w * random(0.5, 0.75));
			let h2 = (w - h1);
			drawBuilding(x + (w - w1) / 2, y + (w - h1) / 2, w1, w2, h1, h2, -1);
		}
	}
}

function draw() {

}

function drawBuilding(x, y, w1, w2, h1, h2, sclX) {
	shuffle(colors, true);
	let clr1 = colors[1];
	let clr2 = colors[2];
	let clr3 = colors[3];
	push();
	translate(x, y);
	scale(sclX, 1);

	noStroke();
	fill(shadowColor(clr1));
	beginShape();
	vertex(-(w1 / 2), -(h1 / 2));
	vertex(0, -(h1 / 2) - h2);
	vertex((w1 / 2), -(h1 / 2));
	vertex((w1 / 2), (h1 / 2));
	vertex(-(w1 / 2), (h1 / 2));
	endShape(CLOSE);

	fill(clr1);
	beginShape();
	vertex((w1 / 2), -(h1 / 2));
	vertex((w1 / 2) + w2, -(h1 / 2));
	vertex((w1 / 2) + w2, (h1 / 2));
	vertex((w1 / 2), (h1 / 2));
	endShape(CLOSE);

	fill(clr2);
	beginShape();
	vertex(0, -(h1 / 2) - h2);
	vertex((w2), -(h1 / 2) - h2);
	vertex((w2) + (w1 / 2), -(h1 / 2));
	vertex((w1 / 2), -(h1 / 2));
	endShape(CLOSE);

	fill(shadowColor(clr3));
	drawGrid(0, 0, w1 * 0.9, h1 * 0.9, int(random(1, 4)), int(random(1, 4)));
	fill(clr3);
	drawGrid((w1 + w2) / 2, 0, w2 * 0.9, h1 * 0.9, int(random(1, 4)), int(random(1, 4)));

	pop();
}

function drawGrid(x, y, w, h, col, row) {
	let cellW = w / col;
	let cellH = h / row;
	push();
	translate(x - w / 2, y - h / 2);
	for (let i = 0; i < col; i++) {
		for (let j = 0; j < row; j++) {
			let xx = i * cellW + cellW / 2;
			let yy = j * cellH + cellH / 2;
			rect(xx, yy, cellW * 0.6, cellH * 0.6);
		}
	}
	pop();
}

function shadowColor(clr) {
	let h = (hue(clr) - 9) % 360;
	let s = saturation(clr) + 20;
	let b = brightness(clr) - 20;
	let c = color(h, s, b);
	return c;
}

